// F11 — Expat Retour.
//
// Profils par pays d'origine pour les Français rentrant. Chaque profil contient :
//  - taux de change moyen (€ pour 1 unité de devise locale, jan 2026)
//  - équivalent net pour un même niveau de vie
//  - "ce que tu avais vs ce que tu auras" : items concrets (logement, voiture,
//    santé, fiscalité, services)
//  - admin retour France : 5 étapes prioritaires + lien officiel
//
// Données indicatives, à valider en début d'année avec BCE / OFII. Mention
// systématique : "consultatif, ne remplace pas le conseil d'un expert-comptable
// ou du consulat".

export type ExpatCountry =
  | "suisse"
  | "luxembourg"
  | "belgique"
  | "royaume-uni"
  | "canada"
  | "allemagne"
  | "etats-unis"
  | "espagne"
  | "portugal"
  | "pays-bas"
  | "italie"
  | "maroc"
  | "cote-d-ivoire"
  | "emirats-arabes-unis"
  | "australie"
  | "irlande"
  | "singapour"
  | "japon"
  | "suede"
  | "chine"
  | "bresil"
  | "thailande";

export interface ExpatCountryProfile {
  slug: ExpatCountry;
  name: string;
  flag: string;
  depuisLabel?: string; // article après "Rentrer en France depuis" (défaut "le", ex. "les" pour les États-Unis)
  auLabel?: string; // en-tête de colonne du tableau (défaut "Au", ex. "Aux" pour les États-Unis)
  currency: string;
  currencyToEurApprox: number; // 1 unité locale = X €, janvier 2026 estimé
  netConversionFactor: number; // pour 100 unités locales nettes, tu retrouves ~ X € en France pour vivre pareil (pouvoir d'achat)
  bestSuitedCities: string[]; // slugs CITIES_SEED
  hadVsWillHave: Array<{ topic: string; had: string; willHave: string }>;
  adminPriorities: Array<{ step: string; detail: string; officialUrl?: string }>;
  intro: string;
  warnings: string[];
}

// Countries with an English page under app/[locale]/expat-return/[slug]. The EN
// hub must filter on this: it used to link every FR country, and the twelve
// without a page were 404s.
export const EN_EXPAT_COUNTRY_SLUGS = new Set([
  "suisse",
  "luxembourg",
  "belgique",
  "royaume-uni",
  "canada",
  "etats-unis",
]);

/**
 * Projection maigre pour `components/ExpatQuiz.tsx`, qui est un composant
 * client et n'a besoin que de l'étiquette du bouton et de la liste de villes
 * frontalières. Ce module fait 190 Ko — vingt et une fiches de prose, de
 * chiffres et de liens administratifs — et un tableau de littéraux n'est pas
 * tree-shakable : l'importer en **valeur** depuis le quiz expédiait tout au
 * navigateur (CLAUDE.md § Performance, même piège que `@/data/guides`).
 *
 * La page serveur `app/expat-retour/quiz` passe cette liste en prop, comme elle
 * passe déjà `CITIES_LIGHT` — donc rien à maintenir en double : un pays ajouté
 * à `EXPAT_COUNTRIES` apparaît dans le quiz sans autre geste.
 */
export type ExpatCountryOption = Pick<
  ExpatCountryProfile,
  "slug" | "name" | "flag" | "bestSuitedCities"
>;

